#nullable enable // autogenerated  
  
using System.Collections.Generic;  
using MVZ2.Vanilla.Entities;  
using MVZ2Logic.Entities;  
using MVZ2Logic.Artifacts;  
using MVZ2Logic.Definitions;  
using MVZ2Logic.Level;  
using PVZEngine.Entities;  
  
namespace MVZ2.GameContent.Artifacts  
{  
    [AutoArtifactDefinition(VanillaArtifactNames.sweetSleepPillow)]  
    public class SweetSleepPillow : ArtifactDefinition  
    {  
        public SweetSleepPillow(string nsp, string name) : base(nsp, name)  
        {  
        }  
  
        // 记录每个器械上一帧的血量，用于判断是否刚受到伤害  
        private readonly Dictionary<Entity, float> lastHealth = new Dictionary<Entity, float>();  
        private const float HealthTolerance = 0.01f;  
  
        public override void PostUpdate(Artifact artifact)  
        {  
            base.PostUpdate(artifact);  
            if (artifact.Level.IsAllEnemiesCleared() || artifact.Level.IsCleared)  
            {  
                artifact.SetGlowing(false);  
                return;  
            }  
  
            artifact.SetGlowing(true);  
            var level = artifact.Level;  
  
            var contraptions = new List<Entity>();  
            foreach (var contraption in level.FindEntities(e => e.Type == EntityTypes.PLANT && e.IsFriendlyEntity()))  
            {  
                contraptions.Add(contraption);  
  
                bool tookDamage = lastHealth.TryGetValue(contraption, out var prevHealth)  
                    && contraption.Health < prevHealth - HealthTolerance;  
  
                // 只有在器械本帧没有受到伤害时才治疗  
                if (!tookDamage)  
                {  
                    contraption.HealEffects(0.33333333f, contraption);  
                }  
  
                // 记录（可能已被治疗后的）当前血量，供下一帧比较  
                lastHealth[contraption] = contraption.Health;  
            }  
  
            // 清理已不存在的器械，避免字典无限增长  
            if (lastHealth.Count > contraptions.Count)  
            {  
                var toRemove = new List<Entity>();  
                foreach (var kv in lastHealth)  
                {  
                    if (!contraptions.Contains(kv.Key))  
                        toRemove.Add(kv.Key);  
                }  
                foreach (var e in toRemove)  
                    lastHealth.Remove(e);  
            }  
        }  
    }  
}